package com.guillermomolina.protos.execution;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import org.junit.jupiter.api.Test;

/**
 * I109-A / PLAT063-C source-emission structural regression guards.
 *
 * <p>These tests verify the Bytecode DSL emission source, not the
 * instructions materialized by the generated BytecodeNode.
 */
final class ProtosI109ASharedLocalEachLoweringTest {

    private static final String[] FAMILIES = {
        "Array", "Bytes", "Environment", "IdentityMap", "Map"
    };

    private static final String[] OPERATIONS = {
        "IsStructuredLocalEachCall",
        "PrepareStructuredLocalEachCall",
        "StructuredLocalEachHasNext",
        "PrepareStructuredLocalEachChildCall",
        "AdvanceStructuredLocalEach",
        "FinishStructuredLocalEach"
    };

    private static Path repositoryFile(String relative) {
        Path directory = Path.of("").toAbsolutePath();

        while (directory != null) {
            if (Files.isRegularFile(directory.resolve("pom.xml"))
                    && Files.isRegularFile(directory.resolve(relative))) {
                return directory.resolve(relative);
            }
            directory = directory.getParent();
        }

        throw new IllegalStateException(
                "Cannot find repository file: " + relative);
    }

    private static String read(String relative) throws IOException {
        return Files.readString(repositoryFile(relative));
    }

    private static String lowering() throws IOException {
        return read(
                "src/main/java/com/guillermomolina/protos/"
                + "execution/bytecode/lowering/"
                + "ProtosStructuredDispatchLowerer.java");
    }

    private static String activation() throws IOException {
        return read(
                "src/main/java/com/guillermomolina/protos/"
                + "execution/bytecode/activation/"
                + "ProtosBytecodeRootNode.java");
    }

    private static int occurrences(String text, String token) {
        int count = 0;
        int position = 0;

        while ((position = text.indexOf(token, position)) >= 0) {
            count++;
            position += token.length();
        }

        return count;
    }

    private static String sharedRegion(String source) {
        String first = "builder.beginIsStructuredLocalEachCall();";
        String foreign = "builder.beginIsStructuredForeignEachCall();";

        int start = source.indexOf(first);
        int end = source.indexOf(foreign);

        assertTrue(start >= 0, "Shared local each admission missing");
        assertTrue(end > start, "Foreign each must follow local each");

        return source.substring(start, end);
    }

    private static String operationClass(String source, String name) {
        String declaration = "public static final class " + name + " {";
        int start = source.indexOf(declaration);

        assertTrue(start >= 0, "Missing operation class " + name);

        int opening = source.indexOf('{', start);
        int depth = 0;

        for (int i = opening; i < source.length(); i++) {
            char character = source.charAt(i);

            if (character == '{') {
                depth++;
            } else if (character == '}') {
                depth--;
                if (depth == 0) {
                    return source.substring(start, i + 1);
                }
            }
        }

        throw new AssertionError("Unbalanced operation class " + name);
    }

    @Test
    void fiveFamiliesShareOnePhysicalBytecodeDslLoop()
            throws IOException {
        String source = lowering();
        String region = sharedRegion(source);

        for (String operation : OPERATIONS) {
            assertEquals(1, occurrences(
                    region, "builder.begin" + operation + "();"),
                    operation);
            assertEquals(1, occurrences(
                    region, "builder.end" + operation + "();"),
                    operation);
        }

        assertEquals(1, occurrences(
                region, "builder.beginWhile();"));
        assertEquals(1, occurrences(
                region, "builder.endWhile();"));

        assertEquals(1, occurrences(
                region, "builder.beginTryFinally("));
        assertEquals(1, occurrences(
                region, "builder.endTryFinally();"));

        assertEquals(1, occurrences(
                region, "builder.beginCompleteClosureCall();"));

        assertEquals(1, occurrences(
                region, "emitScopedPreparedInvocation("));

        for (String family : FAMILIES) {
            assertFalse(source.contains(
                    "builder.beginIsStructured" + family
                    + "EachCall();"),
                    "Old physical branch remains: " + family);
        }
    }

    @Test
    void preparationCallbackAdvanceAndFinishKeepTheirOrder()
            throws IOException {
        String region = sharedRegion(lowering());

        String[] sequence = {
            "builder.beginPrepareStructuredLocalEachCall();",
            "builder.beginWhile();",
            "builder.beginStructuredLocalEachHasNext();",
            "builder.beginPrepareStructuredLocalEachChildCall();",
            "emitScopedPreparedInvocation(",
            "builder.beginAdvanceStructuredLocalEach();",
            "builder.endWhile();",
            "builder.beginFinishStructuredLocalEach();"
        };

        int previous = -1;

        for (String operation : sequence) {
            int current = region.indexOf(operation);
            assertTrue(
                    current > previous,
                    "Missing or reordered operation: " + operation);
            previous = current;
        }
    }

    @Test
    void admissionUsesCapabilitiesNotSelectorText()
            throws IOException {
        String source = activation();
        String admission = operationClass(
                source, "IsStructuredLocalEachCall");

        for (String family : FAMILIES) {
            assertTrue(admission.contains(
                    "prepared.isStructured" + family + "Each()"),
                    "Missing capability: " + family);
        }

        assertFalse(admission.contains("\"each\""));

        assertTrue(admission.contains(
                "OrdinarySourceCall prepared"));
        assertTrue(admission.contains(
                "NativeCall prepared"));
        assertTrue(admission.contains(
                "ImmediateResultCall prepared"));
        assertTrue(admission.contains(
                "ModuleInitializationCall prepared"));
    }

    @Test
    void preparationDelegatesToTheFiveExistingAuthorities()
            throws IOException {
        String source = activation();
        String preparation = operationClass(
                source, "PrepareStructuredLocalEachCall");

        for (String family : FAMILIES) {
            assertEquals(4, occurrences(
                    preparation,
                    "return PrepareStructured" + family
                    + "EachCall."),
                    "Incorrect number of delegates: " + family);
        }

        assertFalse(preparation.contains("\"each\""));
    }

    @Test
    void unrelatedDispatchFamiliesRemainPresent()
            throws IOException {
        String source = lowering();

        assertEquals(1, occurrences(
                source,
                "builder.beginIsStructuredForeignEachCall();"));

        assertEquals(1, occurrences(
                source,
                "builder.beginIsStructuredIdentityMapAtIfAbsentCall();"));

        assertEquals(1, occurrences(
                source,
                "builder.beginIsStructuredMapReadLookupCall();"));

        assertTrue(
                source.indexOf("builder.beginIsStructuredLocalEachCall();")
                < source.indexOf("builder.beginIsStructuredForeignEachCall();"));

        assertTrue(
                source.indexOf("builder.beginIsStructuredForeignEachCall();")
                < source.indexOf(
                        "builder.beginIsStructuredIdentityMapAtIfAbsentCall();"));
    }
}
